import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {spawnSync} from 'node:child_process';import {checkVerdict} from '../../scripts/gate-check.mjs';
const repo=process.cwd(),tmp=fs.mkdtempSync(path.join(repo,'.review-probe-'));let checks=0;const check=(x,label)=>{assert(x,label);checks++;console.log('PASS '+label)};
const run=(script,args=[])=>spawnSync(process.execPath,[script,...args],{encoding:'utf8'});
try{const source=path.join(tmp,'source'),lib=path.join(source,'scripts/lib'),install=path.join(tmp,'install');fs.mkdirSync(lib,{recursive:true});
fs.writeFileSync(path.join(source,'scripts/wave-entry.mjs'),`import {createRequire as factory} from 'node:module';const require=factory(import.meta.url);require(\n './lib/a.cjs'\n);export * from './lib/b.js';import('./lib/c.mjs');const text="from './missing.cjs' require('./missing.cjs')";/* require('./missing.cjs') */const template=\`require('./missing.cjs')\`;const regex=/require\\('\\.\\/missing.cjs'\\)/;`);
fs.writeFileSync(path.join(lib,'a.cjs'),"require('./b.js');");fs.writeFileSync(path.join(lib,'b.js'),"require('./a.cjs');");fs.writeFileSync(path.join(lib,'c.mjs'),"export * from './d.mjs';");fs.writeFileSync(path.join(lib,'d.mjs'),'export const x=1;');const ship=()=>run('scripts/ship-wave.mjs',[source,install]);check(ship().status===0,'multiline createRequire binding named require, cycle, ESM and prose');check(fs.existsSync(path.join(install,'scripts/lib/d.mjs')),'transitive closure');
fs.writeFileSync(path.join(lib,'d.mjs'),"require('./missing.cjs');");check(ship().stderr.includes('dependency missing'),'missing refuses');fs.writeFileSync(path.join(tmp,'outside.cjs'),'');fs.writeFileSync(path.join(lib,'d.mjs'),"require('../../../outside.cjs');");check(ship().stderr.includes('escapes scripts'),'escape refuses');
fs.unlinkSync(path.join(lib,'d.mjs'));try{fs.symlinkSync(path.join(tmp,'outside.cjs'),path.join(lib,'d.mjs'));check(ship().stderr.includes('escapes scripts'),'symlink realpath refuses');}catch(e){console.log('SKIP symlink creation: '+e.code);} 
for(const [exit,text,ok] of [[0,'deploy shipped ok (98 checks)',true],[7,'deploy shipped ok (98 checks)',false],[0,'deploy shipped ok (1 checks)',false],[0,'deploy shipped ok (98 checks)\nFAIL broken',false],[0,'deploy shipped ok (98 checks, 1 skipped)',false]])check(checkVerdict({verdict:'proof',proof_kind:'deployShipped',minimum:76},exit,text).ok===ok,'pure proof '+JSON.stringify([exit,text]));check(checkVerdict({verdict:'js'},0,'ALL PASS\n').ok,'pure JS verdict');check(!checkVerdict({verdict:'js'},7,'ALL PASS\n').ok,'pure JS bad exit');
// Mutate only a disposable copy, never producer or review production source.
const mutant=path.join(tmp,'mutant');fs.mkdirSync(mutant);fs.cpSync('scripts',path.join(mutant,'scripts'),{recursive:true});fs.cpSync('rust',path.join(mutant,'rust'),{recursive:true,filter:p=>!p.includes('target')});fs.cpSync('jobs',path.join(mutant,'jobs'),{recursive:true});fs.cpSync('skills',path.join(mutant,'skills'),{recursive:true});fs.cpSync('lua',path.join(mutant,'lua'),{recursive:true});fs.cpSync('ui',path.join(mutant,'ui'),{recursive:true});
const old=spawnSync('git',['show','3f54a90:scripts/ship-wave.mjs'],{encoding:'utf8'});assert.equal(old.status,0);fs.writeFileSync(path.join(mutant,'scripts/ship-wave.mjs'),old.stdout);
for(const name of ['test-wave-ship','check-deploy-shipped']){const r=spawnSync(process.execPath,[path.join(mutant,'scripts',name+'.mjs')],{cwd:mutant,encoding:'utf8'});console.log('BASELINE MUTATION '+name+' exit='+r.status+'\n'+r.stdout+r.stderr);check(r.status===0,'normal existing path misses CJS regression: '+name);}
console.log('independent probes ok ('+checks+' checks; symlink skip reported separately)');}finally{fs.rmSync(tmp,{recursive:true,force:true});}
